import { MakeLogicType, actions, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { organizationLogic } from 'scenes/organizationLogic'

import type { OrganizationType } from '~/types'

import * as api from '../generated/api'
import type { CustomerSubmissionStateApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentTranscriptSubmissionLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    submission: CustomerSubmissionStateApi | null
    submissionLoadFailed: boolean
    submissionLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentTranscriptSubmissionLogicActions {
    loadSubmission: () => any
    loadSubmissionFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSubmissionSuccess: (
        submission: CustomerSubmissionStateApi | null,
        payload?: any
    ) => {
        submission: CustomerSubmissionStateApi | null
        payload?: any
    }
    setSubmission: (submission: CustomerSubmissionStateApi) => {
        submission: CustomerSubmissionStateApi
    }
}

export type agentTranscriptSubmissionLogicType = MakeLogicType<
    agentTranscriptSubmissionLogicValues,
    agentTranscriptSubmissionLogicActions
>

/** The organization's submission, shared by the request card and the submission page so both show one state. */
export const agentTranscriptSubmissionLogic = kea<agentTranscriptSubmissionLogicType>([
    path(['products', 'agent_transcripts', 'frontend', 'agentTranscriptSubmissionLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganization']],
    })),
    actions({
        setSubmission: (submission: CustomerSubmissionStateApi) => ({ submission }),
    }),
    loaders(({ values }) => ({
        submission: [
            null as CustomerSubmissionStateApi | null,
            {
                loadSubmission: async () => {
                    const organizationId = values.currentOrganization?.id
                    if (!organizationId) {
                        return null
                    }

                    return await api.agentTranscriptsSubmissionRetrieve(organizationId)
                },
            },
        ],
    })),
    reducers({
        submission: {
            setSubmission: (_, { submission }) => submission,
        },
        submissionLoadFailed: [
            false,
            {
                loadSubmission: () => false,
                loadSubmissionSuccess: () => false,
                loadSubmissionFailure: () => true,
            },
        ],
    }),
])
